function getAllSeasons() {
  const url = 'https://docs.google.com/spreadsheets/d/1hkpIVT1kp7gdMI9BPNOkznFXUqTTRACItNhOvry26Gg/edit#gid=0';
  const ss = SpreadsheetApp.openByUrl(url);
  const seasonSheet = ss.getSheetByName("시즌목록");

  // A열에서 과거 시즌 목록을 가져옵니다.
  const pastSeasons = seasonSheet.getRange("A2:A" + seasonSheet.getLastRow()).getValues()
                                 .flat()
                                 .filter(String)
                                 .map(s => s.trim());

  // E열에서 현재 시즌 정보를 가져옵니다.
  const currentSeason = seasonSheet.getRange("E2").getValue().toString().trim();

  // 현재 시즌, 그리고 과거 시즌을 순서대로 배열에 담습니다.
  const sortedSeasons = [currentSeason, ...pastSeasons];

  return sortedSeasons;
}

