function loadPoint(userId, season) {
  const url = 'https://docs.google.com/spreadsheets/d/1hkpIVT1kp7gdMI9BPNOkznFXUqTTRACItNhOvry26Gg/edit#gid=0';
  const ss = SpreadsheetApp.openByUrl(url);
  const ws = ss.getSheetByName("포인트변동");

  let data = [];
  let returnData = [];
  try{
    data = ws.getRange(2,2,ws.getLastRow()-1,4).getValues();
  }
  catch(e)
  {
    returnData.push([Utilities.formatDate(new Date(),'GMT+9', 'yyyy-MM-dd HH:mm'),
                    userId,
                    0
                    ]);
    return returnData;
  }
  let dataFilter = data.filter( (row) => ( row[1] == userId && row[3] == season));

  for (let index = 0; index < dataFilter.length; index++){
      if(index > 10) break;

      returnData.push([dataFilter[index][0], //날짜
                       dataFilter[index][1], //ID
                       dataFilter[index][2], //Point
                    ]);
  }
  if(returnData.length == 0){
    returnData.push([Utilities.formatDate(new Date(),'GMT+9', 'yyyy-MM-dd HH:mm'),
                    userId,
                    0
                    ]);
  }
  returnData.sort()
  console.log(returnData)
  return returnData;
}

function loadStat(curSeason) {
    // [주의] 이 URL은 Google Apps Script의 SpreadsheetApp.openByUrl에 사용되는 URL입니다.
    const url = 'https://docs.google.com/spreadsheets/d/1hkpIVT1kp7gdMI9BPNOkznFXUqTTRACItNhOvry26Gg/edit#gid=0';
    const ss = SpreadsheetApp.openByUrl(url);

    // --- 1. 특별 인장 정보 로드 및 맵핑 (추가된 로직) ---

    const userListSheet = ss.getSheetByName("사용자목록");
    let achievementMap = {}; // {닉네임: true/false} 형태로 저장할 맵

    if (userListSheet) {
        // A열(닉네임, index 0)부터 AB열(특별인장, index 27)까지 데이터를 읽습니다.
        // A1은 헤더라고 가정하고 A2부터 마지막 행까지 읽습니다.
        const lastRow = userListSheet.getLastRow();
        if (lastRow > 1) {
            // getRange(시작 행, 시작 열, 행 수, 열 수) -> A2:AB[lastRow]
            const userListData = userListSheet.getRange(2, 1, lastRow - 1, 28).getValues(); 

            userListData.forEach(row => {
                const nickname = row[0]; // A열 값
                const badgeStatus = row[27]; // AB열 값 (A=1열, AB=28열, 배열 인덱스는 27)

                if (nickname) {
                    // 'Y'이면 true, 아니면 false로 저장합니다.
                    achievementMap[nickname] = (badgeStatus === 'Y'); 
                }
            });
        }
    }

    // --- 2. 시즌 전적 데이터 로드 ---

    let targetSheetName = "";
    console.log("입력값:" + curSeason)
    // NOTE: getCurrentSeason() 함수가 정의되어 있어야 합니다.
    if( curSeason == getCurrentSeason()){ 
        targetSheetName = "전적확인";
    }
    else{
        targetSheetName = "전적확인_" + curSeason;
    }

    const ws = ss.getSheetByName(targetSheetName);

    let data = [];
    let returnData = [];

    try{
        data = ws.getRange(2,1,ws.getLastRow()-1,25).getValues();
    }
    catch(e)
    {
        // 시트가 없거나 데이터 범위 오류 시 빈 배열 반환
        return returnData;
    }

    // --- 3. 데이터 가공 및 반환 (특별 인장 정보 추가) ---

    for (let index = 0; index < data.length; index++){
        // data[index][19]는 '제외' 여부 (T열)
        if( data[index][19] == 'Y'){
            continue;
        }

        const date = data[index][18]; // 날짜
        const year = date.getFullYear();
        const month = ('0' + (date.getMonth() + 1)).slice(-2);
        const day = ('0' + date.getDate()).slice(-2);
        const dateStr = `${year}-${month}-${day}`;

        // 특별 인장 여부 확인 (닉네임: data[index][0])
        const nickname = data[index][0];
        // achievementMap에서 조회, 값이 없으면 기본값으로 false 처리
        const hasSpecialBadge = achievementMap[nickname] || false; 

        returnData.push([
            data[index][0], // 0. ID (닉네임)
            data[index][1], // 1. 드루_승 
            data[index][2], // 2. 드루_패 
            data[index][3], // 3. 어쎄_승 
            data[index][4], // 4. 어쎄_패 
            data[index][5], // 5. 네크_승 
            data[index][6], // 6. 네크_패 
            data[index][7], // 7. 슴딘_승 
            data[index][8], // 8. 슴딘_패 
            data[index][9], // 9. 종합_승 
            data[index][10], // 10. 종합_패 
            data[index][11], // 11. 종합_승률 
            data[index][12], // 12. 드루_승률 
            data[index][13], // 13. 어쎄_승률 
            data[index][14], // 14. 네크_승률 
            data[index][15], // 15. 슴딘_승률 
            data[index][16], // 16. 순위 
            data[index][17], // 17. 점수 
            dateStr, // 18. 최근플레이날짜 
            data[index][21], // 19. (원래 데이터의 22번째 열)
            data[index][23], // 20. 순위 증감 (원래 데이터의 24번째 열)
            hasSpecialBadge // 21. 특별 인장 여부 (true 또는 false)
        ]);
    }

    console.log(returnData);
    return returnData;
}

