function loadUser_Medal() {
  const url = 'https://docs.google.com/spreadsheets/d/1hkpIVT1kp7gdMI9BPNOkznFXUqTTRACItNhOvry26Gg/edit#gid=0';
  const ss = SpreadsheetApp.openByUrl(url);
  var sheet = ss.getSheetByName('사용자목록');

  var range = sheet.getDataRange();
  var values = range.getValues();

  var trophyIndex = 6; // G열 (트로피 정보) 인덱스 (0부터 시작)
  var userIdIndex = 0; // A열 (유저 ID) 인덱스

  // 🏅 G열(트로피)이 비어있지 않은 행만 필터링
  var filteredData = values.slice(1).filter(row => row[trophyIndex] && row[trophyIndex].trim() !== "");

  // 🏆 트로피 정보를 분석하여 메달 개수 추출 (숫자 포함)
  function parseTrophy(trophyString) {
    var goldMatch = trophyString.match(/🥇(\d+)/); // "🥇3" → 3 추출
    var silverMatch = trophyString.match(/🥈(\d+)/); // "🥈2" → 2 추출
    var bronzeMatch = trophyString.match(/🥉(\d+)/); // "🥉1" → 1 추출

    var gold = goldMatch ? parseInt(goldMatch[1]) : 0;
    var silver = silverMatch ? parseInt(silverMatch[1]) : 0;
    var bronze = bronzeMatch ? parseInt(bronzeMatch[1]) : 0;

    return { gold, silver, bronze, score: gold * 3 + silver * 2 + bronze * 1 };
  }

  // 🏆 메달 개수 및 점수 계산
  var sortedData = filteredData.map(row => {
    var trophies = parseTrophy(row[trophyIndex]);
    return {
      userId: row[userIdIndex], // 유저 ID
      trophyInfo: row[trophyIndex], // 트로피 정보 원본
      score: trophies.score,
      gold: trophies.gold
    };
  });

  // 📊 점수 기준 내림차순 정렬 (score가 같다면 금메달 개수로 정렬)
  sortedData.sort((a, b) => {
    if (b.score !== a.score) {
      return b.score - a.score; // 점수 기준 정렬
    }
    return b.gold - a.gold; // 금메달 개수 기준 정렬
  });

  // 📢 결과 JSON 반환 (아이디 / 트로피 정보만)
  return sortedData.map(player => ({
    userId: player.userId,
    trophyInfo: player.trophyInfo
  }));
}




