/**
 * '시즌목록' 시트의 E2, G2, F2 셀 값을 가져와 반환합니다.
 * @return {object} E2, G2, F2 셀 값을 담은 객체.
 */
function getSeasonData() {
  try {
    const url = 'https://docs.google.com/spreadsheets/d/1hkpIVT1kp7gdMI9BPNOkznFXUqTTRACItNhOvry26Gg/edit#gid=0';
    const ss = SpreadsheetApp.openByUrl(url);
    const ws = ss.getSheetByName('시즌목록');

    // 시트가 존재하지 않으면 오류를 반환합니다.
    if (!ws) {
      throw new Error("시트 '시즌목록'을 찾을 수 없습니다.");
    }

    // E2, G2, F2 셀을 가져와 값을 읽습니다.
    const currSeasonValue = ws.getRange('E2').getValue();
    const startDateValue = ws.getRange('F2').getValue();
    const endDateValue = ws.getRange('G2').getValue();

    // 객체 형태로 값을 반환합니다.
    return {
      currSeason: currSeasonValue,
      startDate: startDateValue,
      endDate: endDateValue
    };

  } catch (e) {
    // 오류 발생 시 로그를 남기고 빈 객체를 반환합니다.
    console.error("오류 발생: " + e.message);
    return {};
  }
}

function getDuoStats() {
  const url = 'https://docs.google.com/spreadsheets/d/1hkpIVT1kp7gdMI9BPNOkznFXUqTTRACItNhOvry26Gg/edit#gid=0';
  const ss = SpreadsheetApp.openByUrl(url);
  const sheet = ss.getSheetByName('듀오전적');

  if (!sheet) {
    return { error: '듀오전적 시트를 찾을 수 없습니다.' };
  }

  const lastRow = sheet.getLastRow();
  if (lastRow < 2) {
    return { error: '데이터가 없습니다.' };
  }

  // 현재 시즌 정보를 가져옵니다.
  const currentSeason = getCurrentSeason();

  // 헤더를 제외한 모든 데이터를 가져옵니다. (시즌, 듀오이름, 승리, 패배, 기타...)
  const dataRange = sheet.getRange(2, 1, lastRow - 1, 5);
  let data = dataRange.getValues();

  // 현재 시즌에 해당하는 데이터만 필터링합니다.
  const filteredBySeason = data.filter(row => row[0] === currentSeason);

  // 10판 이상 플레이한 듀오만 필터링하고 승률을 계산합니다.
  const filteredData = filteredBySeason.filter(row => {
    const wins = row[2]; // C열 (승리)
    const losses = row[3]; // D열 (패배)
    return (wins + losses) >= 10;
  }).map(row => {
    const wins = row[2];
    const losses = row[3];
    const totalGames = wins + losses;
    const winRate = totalGames > 0 ? (wins / totalGames) : 0;

    // 필요한 데이터를 객체 형태로 정리하여 반환합니다.
    return {
      duoName: row[1], // B열 (듀오이름)
      wins: wins,
      losses: losses,
      winRate: winRate
    };
  });

  // 승률 기준 Top 5 추출을 위해 정렬합니다. (내림차순)
  filteredData.sort((a, b) => b.winRate - a.winRate);
  const top5 = filteredData.slice(0, 5);

  // 승률 기준 Bottom 5 추출을 위해 정렬합니다. (오름차순)
  filteredData.sort((a, b) => a.winRate - b.winRate);
  const bottom5 = filteredData.slice(0, 5);

  // 결과를 객체 형태로 반환합니다.
  return { top: top5, bottom: bottom5 };
}

/**
