    return { error: '데이터가 없습니다.' };
  }

  // 헤더를 제외한 모든 데이터를 가져옵니다.
  const dataRange = sheet.getRange(2, 1, sheet.getLastRow() - 1, 5);
  const data = dataRange.getValues();

  // 데이터 정렬
  data.sort((a, b) => {
