/**
 * 지정된 스프레드시트에서 듀오전적을 필터링하여 가져옵니다.
 *
 * @param {string} seasonName 필터링할 시즌 정보 (A열)
 * @returns {Array<Array>} 필터링된 데이터 배열
 */
function loadFilteredDuoStats(seasonName) {
  const url = 'https://docs.google.com/spreadsheets/d/1hkpIVT1kp7gdMI9BPNOkznFXUqTTRACItNhOvry26Gg/edit#gid=0';
  const ss = SpreadsheetApp.openByUrl(url);
  const sheet = ss.getSheetByName('듀오전적');

  if (!sheet) {
    Logger.log("'듀오전적' 시트를 찾을 수 없습니다.");
    return [];
  }

  // 데이터 범위를 동적으로 가져옵니다. (시작 행 2, 열 1)
  const allData = sheet.getRange(2, 1, sheet.getLastRow() - 1, sheet.getLastColumn()).getValues();

  // 시즌 정보와 총 게임 수(3판 이상)를 기준으로 데이터를 필터링합니다.
  const filteredData = allData.filter(row => {
    // A열의 시즌 정보와 일치하는지 확인합니다.
    const isSeasonMatch = row[0] === seasonName;

    // 총 게임 수(C열과 D열의 합)가 3 이상인지 확인합니다.
    const totalGames = row[2] + row[3];
    const isOverThreeGames = totalGames >= 3;

    return isSeasonMatch && isOverThreeGames;
  });

  // 필터링된 데이터에서 B, C, D, E 열만 추출하여 새로운 배열을 만듭니다.
  // 원본 배열에서 인덱스 1(B열)부터 4(E열)까지의 데이터를 가져옵니다.
  const resultData = filteredData.map(row => [row[1], row[2], row[3], row[4]]);

  Logger.log(resultData);
  return resultData;
}

/**
 * @param {string} userId - 정보를 조회할 사용자의 ID.
 * @return {Array<Array<string>>} 최근 5경기 정보를 담은 배열.
 * 각 내부 배열은 [경기일자, 캐릭터, 스코어, 승패]로 구성됩니다.
 */
function getUserRecentGames(userId) {
  // 스프레드시트 URL로 접근
  const url = 'https://docs.google.com/spreadsheets/d/1hkpIVT1kp7gdMI9BPNOkznFXUqTTRACItNhOvry26Gg/edit#gid=0';
  const ss = SpreadsheetApp.openByUrl(url);
  const sheet = ss.getSheetByName('전적이력');
  if (!sheet) {
    return [['오류', '전적이력 시트를 찾을 수 없습니다.', '', '']];
  }

  const dataRange = sheet.getDataRange();
  const values = dataRange.getValues();
  values.shift(); // 헤더 행 제거

  const recentGames = [];
  const maxGames = 5;

  // 데이터를 위에서부터 순차적으로 탐색 (최신 데이터가 가장 위에 있으므로)
  for (let i = 0; i < values.length && recentGames.length < maxGames; i++) {
    const row = values[i];
    const gameDate = row[1]; // B열: 경기날짜
    const winTeamInfo = row[2]; // C열: 승리팀
    const loseTeamInfo = row[4]; // E열: 패배팀
    const winPoints = row[3]; // D열: WP (승리포인트)
    const losePoints = row[5]; // F열: LP (패배포인트)

    let character = '';
    let result = '';
    let score = '';

    // 승리팀에 ID가 있는지 확인
    if (winTeamInfo && winTeamInfo.includes(userId)) {
      result = '승리';
      character = extractCharacter(winTeamInfo, userId);
      score = `${winPoints}:${losePoints}`;
    } else if (loseTeamInfo && loseTeamInfo.includes(userId)) { // 패배팀에 ID가 있는지 확인
      result = '패배';
      character = extractCharacter(loseTeamInfo, userId);
      score = `${losePoints}:${winPoints}`; // 패배팀 입장에서는 스코어가 반대로 표시
    }

    // 결과가 있는 경우에만 배열에 추가
    if (result) {
      // 날짜 형식을 'YYYY-MM-DD'로 변경
      const formattedDate = Utilities.formatDate(new Date(gameDate), "GMT+9", "yyyy-MM-dd HH:mm");
      recentGames.push([formattedDate, character, score, result]);
    }
  }

  return recentGames;
}

/**
 * @param {string} teamInfo - 팀 정보 문자열.
 * @param {string} userId - 사용자의 ID.
 * @return {string} 사용자가 플레이한 캐릭터 이름.
 */
function extractCharacter(teamInfo, userId) {
  const characters = ['드루', '어쎄', '네크', '슴딘'];
  const players = teamInfo.split('<br>');

  for (let i = 0; i < players.length; i++) {
    const playerText = players[i].replace(/\(.*\)/, '').trim();
    if (playerText === userId) {
      return characters[i];
    }
  }
  return '알 수 없음';
}

