/**
 * @param {string} userName
 * @param {string} seasonName
 * @return {object}
 */
function getDuoStatsForUser(userName, seasonName) {
  // 사용자가 제공한 URL로 스프레드시트를 엽니다.
  const url = 'https://docs.google.com/spreadsheets/d/1hkpIVT1kp7gdMI9BPNOkznFXUqTTRACItNhOvry26Gg/edit#gid=0';
  const ss = SpreadsheetApp.openByUrl(url);
  const sheet = ss.getSheetByName('듀오전적');

  if (!sheet) {
    return { error: '듀오전적 시트를 찾을 수 없습니다.' };
  }

  const data = sheet.getDataRange().getValues();
  const duoStats = {};

  // 데이터의 첫 행(헤더)을 건너뛰고, 각 행을 순회하며 듀오 전적을 집계합니다.
  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    const season = row[0]; // 시즌 이름 (A열)
    const duoName = row[1]; // 듀오 조합 이름 (B열)
    const wins = row[2]; // 승리 횟수 (C열)
    const losses = row[3]; // 패배 횟수 (D열)

    // 요청한 시즌과 일치하고, 사용자 이름이 포함된 데이터만 처리합니다.
    if (season === seasonName) {
        const users = duoName.split('&').map(name => name.trim());

        if (users.includes(userName)) {
          // 데이터가 항상 '깡패&한메'처럼 정렬된 형태로 들어가므로,
          // 그대로 duoStats에 승/패 기록을 누적합니다.
          if (duoStats[duoName]) {
            duoStats[duoName].wins += wins;
            duoStats[duoName].losses += losses;
          } else {
            duoStats[duoName] = {
              wins: wins,
              losses: losses
            };
          }
        }
    }
  }

  // 집계된 듀오 전적을 승률과 승/패 수를 기준으로 정렬합니다.
  const allDuos = Object.keys(duoStats).map(duoName => {
    const stats = duoStats[duoName];
    const totalGames = stats.wins + stats.losses;
    const winRate = totalGames > 0 ? (stats.wins / totalGames) * 100 : 0;

    // 이 부분에서 duoName을 재정렬합니다.
    const users = duoName.split('&').map(name => name.trim());
    users.sort((a, b) => {
      if (a === userName) return -1;
      if (b === userName) return 1;
      return a.localeCompare(b);
    });
    const sortedDuoName = users.join(' & ');

    return {
      duoName: sortedDuoName, // 정렬된 듀오 이름으로 변경
      wins: stats.wins,
      losses: stats.losses,
      winRate: parseFloat(winRate.toFixed(2))
    };
  });

  // Best 3 조합 추출: 승률 50% 이상, 승이 많은 순
  const bestDuos = allDuos
    .filter(duo => duo.winRate >= 50) 
    .sort((a, b) => {
      if (b.wins !== a.wins) {
        return b.wins - a.wins;
      }
      return b.winRate - a.winRate;
    })
    .slice(0, 3);

  // Worst 3 조합 추출: 승률 50% 미만, 패가 많은 순
  const worstDuos = allDuos
    .filter(duo => duo.winRate < 50)
    .sort((a, b) => {
      if (b.losses !== a.losses) {
        return b.losses - a.losses;
      }
      return a.winRate - b.winRate;
    })
    .slice(0, 3);

  return {
    best: bestDuos,
    worst: worstDuos
  };
}

/**
 * 스프레드시트에서 특정 두 사용자의 게임 전적을 시즌별로 통계냅니다.
 *
 * @param {string} user1 - 첫 번째 사용자 이름. (예: "전베리")
 * @param {string} user2 - 두 번째 사용자 이름. (예: "덤벼")
 * @param {string} seasonInfo - 통계낼 시즌 정보. (예: "시즌 13")
 * @return {object} - 같은 팀 전적 (win/lose)과 상대 팀 전적 (win/lose)을 담은 객체.
 */
function calculateGameStats(user1, user2, seasonInfo) {
  const url = 'https://docs.google.com/spreadsheets/d/1hkpIVT1kp7gdMI9BPNOkznFXUqTTRACItNhOvry26Gg/edit#gid=0';
  const ss = SpreadsheetApp.openByUrl(url);
  const sheet = ss.getSheetByName('전적이력');

  const dataRange = sheet.getDataRange();
  const values = dataRange.getValues();
  const headers = values[0];
  const allRows = values.slice(1);

  // 전적을 저장할 객체 초기화
  let teamUpStats = { win: 0, lose: 0 };
  let vsStats = { win: 0, lose: 0 };

  // 각 행을 순회하며 데이터 분석
  allRows.forEach(row => {
    // 시즌 정보가 'ALL'이거나, 현재 행의 시즌과 입력된 시즌 정보가 일치하는지 확인합니다.
    const season = row[headers.indexOf("시즌")];
    if (seasonInfo !== "ALL" && season !== seasonInfo) {
      return;
    }

    // 승리팀과 패배팀 데이터를 가져옵니다.
    const winnerTeamString = row[headers.indexOf("승리팀(스코어)")];
    const loserTeamString = row[headers.indexOf("패배팀(스코어)")];

    // 선수 목록을 추출하는 함수 (업데이트됨)
    const getPlayers = (teamString) => {
      if (!teamString) return [];
      // "<br>" 기준으로 문자열을 분리합니다.
      const parts = teamString.split('<br>');
      // 각 부분에서 사용자 이름만 추출합니다.
      return parts.map(part => {
        // 이름과 점수를 나누고, 이름 부분만 트림합니다.
        const namePart = part.split('(')[0];
        return namePart.trim();
      }).filter(name => name.length > 0);
    };

    // 승리팀과 패배팀 선수 목록
    const winnerPlayers = getPlayers(winnerTeamString);
    const loserPlayers = getPlayers(loserTeamString);

    // 두 사용자가 같은 팀인지 확인
    const isUser1InWinnerTeam = winnerPlayers.includes(user1);
    const isUser2InWinnerTeam = winnerPlayers.includes(user2);
    const isUser1InLoserTeam = loserPlayers.includes(user1);
    const isUser2InLoserTeam = loserPlayers.includes(user2);
    const isTeamUp = (isUser1InWinnerTeam && isUser2InWinnerTeam) || (isUser1InLoserTeam && isUser2InLoserTeam);
    const isVs = (isUser1InWinnerTeam && isUser2InLoserTeam) || (isUser1InLoserTeam && isUser2InWinnerTeam);

    if (isTeamUp) {
      // Case 1: 두 사용자가 같은 팀으로 게임한 경우
      if (isUser1InWinnerTeam) {
        teamUpStats.win++;
      } else {
        teamUpStats.lose++;
      }
    } else if (isVs) {
      // Case 2: 두 사용자가 상대편으로 만난 경우
      if (isUser1InWinnerTeam) {
        vsStats.win++;
      } else {
        vsStats.lose++;
      }
    }
  });

  return { teamUpStats, vsStats };
}

/**
 * 웹 앱에서 호출됨: 두 사용자 간의 '직업별' 상대 전적만을 계산하여 반환합니다.
 * 이 함수는 '상세보기' 클릭 시 호출됩니다.
 * * @param {string} user1ID 첫 번째 사용자 ID
 * @param {string} user2ID 두 번째 사용자 ID
 * @param {string} season 조회할 시즌 (ALL 또는 특정 시즌 이름)
 * @returns {object} { 'User1직업': { 'User2직업': { wins: 0, losses: 0 } } } 형태의 직업별 상대 전적 데이터
 */
function getClassHeadToHeadRecordOnly(user1ID, user2ID, season) {
  const url = 'https://docs.google.com/spreadsheets/d/1hkpIVT1kp7gdMI9BPNOkznFXUqTTRACItNhOvry26Gg/edit#gid=0';
  const ss = SpreadsheetApp.openByUrl(url);
  const dataSheet = ss.getSheetByName('전적이력');

  if (!dataSheet) {
    // 에러 처리는 클라이언트에서 사용자에게 알릴 수 있도록 단순 객체 반환
    return { error: "데이터 시트를 찾을 수 없습니다." };
  }

  // 데이터 구조: H열(시즌), J~M열(승리팀 드어넥슴), N~Q열(패배팀 드어넥슴)
  const allData = dataSheet.getRange('A:Q').getValues(); 

  // 전적 계산에 필요한 열 인덱스 (0부터 시작)
  const SEASON_COL = 7; // H열
  const WIN_COLS = [9, 10, 11, 12]; // J, K, L, M열
  const LOSE_COLS = [13, 14, 15, 16]; // N, O, P, Q열
  const classNames = ["드루", "어쎄", "네크", "슴딘"];

  // 직업별 상대 전적 구조 (User1 기준)
  let classH2H = {}; 
  classNames.forEach(c1 => {
    classH2H[c1] = {};
    classNames.forEach(c2 => {
      classH2H[c1][c2] = { wins: 0, losses: 0 };
    });
  });

  // 데이터 순회 (첫 행(헤더) 제외)
  for (let i = 1; i < allData.length; i++) {
    const row = allData[i];
    const gameSeason = String(row[SEASON_COL]).trim();

    // 1. 시즌 필터링
    if (season !== 'ALL' && gameSeason !== season) {
      continue;
    }

    // 2. 직업별 상대 전적 집계 (User1 vs User2)

    // 2-1. User1 승리 (User1: 승리팀, User2: 패배팀)
    for (let j = 0; j < WIN_COLS.length; j++) {
      const u1_winCol = WIN_COLS[j];
      if (row[u1_winCol] === user1ID) {
        for (let k = 0; k < LOSE_COLS.length; k++) {
          const u2_loseCol = LOSE_COLS[k];
          if (row[u2_loseCol] === user2ID) {

            // 직업별 전적 집계
            const u1Class = classNames[j];
            const u2Class = classNames[k];
            classH2H[u1Class][u2Class].wins++;
          }
        }
      }
    }

    // 2-2. User1 패배 (User1: 패배팀, User2: 승리팀)
    for (let j = 0; j < LOSE_COLS.length; j++) {
      const u1_loseCol = LOSE_COLS[j];
      if (row[u1_loseCol] === user1ID) {
        for (let k = 0; k < WIN_COLS.length; k++) {
          const u2_winCol = WIN_COLS[k];
          if (row[u2_winCol] === user2ID) {

            // 직업별 전적 집계
            const u1Class = classNames[j];
            const u2Class = classNames[k];
            classH2H[u1Class][u2Class].losses++;
          }
        }
      }
    }
  }

  return classH2H;
}

/**
 * '사용자목록' 시트에서 플레이어 ID, 티어, 특별인장 정보를 가져와 반환합니다.
 * @returns {Array<Array<string>>} [[ID, Tier, Seal], ...] 형태의 2차원 배열
 */
function loadUserTier() {
  const url = 'https://docs.google.com/spreadsheets/d/1hkpIVT1kp7gdMI9BPNOkznFXUqTTRACItNhOvry26Gg/edit#gid=0';
  const ss = SpreadsheetApp.openByUrl(url); 
  const sheet = ss.getSheetByName('사용자목록');

  if (!sheet) {
    // 시트가 없으면 에러를 로깅하고 빈 배열을 반환합니다.
    Logger.log('Error: Sheet "사용자목록" not found.');
    return [];
  }

  // A열(ID), O열(티어), AB열(특별인장) 데이터 가져오기
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return []; // 헤더(1행) 제외 데이터가 없는 경우

  // 전체 데이터 중 필요한 열을 포함하는 범위(A1:AB[마지막행])를 읽습니다.
  // A열은 1열, O열은 15열, AB열은 28열입니다.
  // getRange(시작 행, 시작 열, 행 개수, 열 개수)
  const range = sheet.getRange(2, 1, lastRow - 1, 28); // 2행부터 마지막행까지 28열(AB열) 범위
  const values = range.getValues();

  // 필요한 열(A, O, AB)만 추출하여 2차원 배열로 반환합니다.
  const ID_COL = 0;   // A열 (0 인덱스)
  const TIER_COL = 14; // O열 (14 인덱스)
  const SEAL_COL = 27; // AB열 (27 인덱스)

  const result = values.map(row => {
    const id = row[ID_COL] ? String(row[ID_COL]).trim() : '';
    const tier = row[TIER_COL] ? String(row[TIER_COL]).trim() : '';
    const seal = row[SEAL_COL] ? String(row[SEAL_COL]).trim() : '';

    return [id, tier, seal];
  }).filter(row => row[0] !== ''); // ID가 비어있지 않은 행만 반환

  return result;
}
